css:
.aha-faq{
  container:aha-faq / inline-size;
  background:var(--aha-white);
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
}
.aha-faq *{box-sizing:border-box}
:where(.aha-faq) h2,:where(.aha-faq) h3,:where(.aha-faq) p{margin:0;padding:0}
.aha-faq__inner{
  display:flex;flex-direction:column;
  --aha-web-gutter:var(--aha-space-64);
  width:100%;max-width:calc(720px + 2 * var(--aha-web-gutter));
  margin:0 auto;
  padding:var(--aha-space-96) var(--aha-web-gutter);
}
.aha-faq__title{
  margin-bottom:var(--aha-space-48);
  display:flex;align-items:center;justify-content:center;text-align:center;
  font-size:var(--aha-size-h2);
  font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-heading);
  color:var(--aha-text-default);
}
.aha-faq__cta{display:flex;flex-wrap:wrap;justify-content:center;gap:var(--aha-space-12);margin-top:var(--aha-space-48)}
.aha-faq__item{border-bottom:1px solid var(--aha-border-default)}
.aha-faq__question{font-size:inherit;font-weight:inherit}
.aha-faq__trigger{
  display:flex;align-items:center;justify-content:space-between;
  width:100%;margin:0;padding:var(--aha-space-24) 0;
  border:0;background:none;border-radius:0;
  font:inherit;text-align:left;color:inherit;cursor:pointer;
}
.aha-faq__heading{display:block;text-align:inherit;
  font-size:var(--aha-size-xl);
  font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-heading);
  color:var(--aha-text-default);
  transition:color var(--aha-motion-fast) var(--aha-ease-out);
}
.aha-faq__icon{
  position:relative;flex:none;
  display:flex;align-items:center;justify-content:center;
  width:var(--aha-space-24);height:var(--aha-space-24);
}
.aha-faq__line{position:absolute;border-radius:var(--aha-radius-xs);background:var(--aha-icon-muted);transition:background-color var(--aha-motion-fast) var(--aha-ease-out)}
.aha-faq__line--horizontal{width:var(--aha-space-12);height:var(--aha-space-2)}
.aha-faq__line--vertical{
  width:var(--aha-space-2);height:var(--aha-space-12);
  transition:transform var(--aha-motion-slow) var(--aha-ease-out),background-color var(--aha-motion-fast) var(--aha-ease-out);
}
.aha-faq__trigger[aria-expanded="true"] .aha-faq__line--vertical{transform:rotate(90deg)}
@media (hover:hover){
  .aha-faq__trigger:hover .aha-faq__heading{color:var(--aha-color-primary)}
  .aha-faq__trigger:hover .aha-faq__line{background:var(--aha-color-primary)}
}
.aha-faq__trigger:focus-visible{
  outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2);
  border-radius:var(--aha-radius-xs);
}
.aha-faq__answer{
  display:grid;grid-template-rows:0fr;visibility:hidden;
  transition:grid-template-rows var(--aha-motion-slow) var(--aha-ease-out),visibility 0s linear var(--aha-motion-slow);
}
.aha-faq__item:has(> .aha-faq__question [aria-expanded="true"]) .aha-faq__answer{
  grid-template-rows:1fr;visibility:visible;
  transition:grid-template-rows var(--aha-motion-slow) var(--aha-ease-out),visibility 0s;
}
.aha-faq__answer-clip{min-height:0;overflow:hidden}
.aha-faq__answer-text{
  padding-bottom:var(--aha-space-32);
  font-size:var(--aha-size-l);
  font-weight:var(--aha-weight-regular);
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-default);
}
@media (prefers-reduced-motion:reduce){
  .aha-faq__answer,.aha-faq__line--vertical,.aha-faq__heading,.aha-faq__line{transition:none}
}
@container aha-faq (max-width:991px){
  .aha-faq__title{font-size:var(--aha-size-h3)}
}
@container aha-faq (max-width:767px){
  .aha-faq__inner{--aha-web-gutter:var(--aha-space-24);}
  .aha-faq__answer-text{padding-bottom:var(--aha-space-24)}
}
@container aha-faq (max-width:479px){
  .aha-faq__title{font-size:var(--aha-size-h4)}
  .aha-faq__inner{--aha-web-gutter:var(--aha-space-16);}
  .aha-faq__cta{margin-top:var(--aha-space-32)}
}
.aha-faq__visually-hidden{
  position:absolute;width:1px;height:1px;margin:-1px;padding:0;
  overflow:hidden;clip-path:inset(50%);white-space:nowrap;
}
